import{V as a}from"./chunks/theme.CLW6cJc4.js";import{c as t,I as r,k as o,a2 as i,o as s}from"./chunks/framework.DdOM6S6U.js";const n=i('<h1 id="what-is-modularous" tabindex="-1">What is Modularous? <a class="header-anchor" href="#what-is-modularous" aria-label="Permalink to &quot;What is Modularous?&quot;">​</a></h1><p><a href="https://github.com/unusualify/modularous" target="_blank" rel="noreferrer">Unusualify/Modularous</a> is a Laravel and Vuetify.js powered, developer tool that aims to improve developer experience on conducting full stack development process. On Laravel side, Modularous manages your large scale projects using modules, where a module similar to a single Laravel project, having some views, controllers or models. With the abilities of Vuetify.js, Modularous presents various of dynamic, configurable UI components to auto-construct a CRM for your project.</p><h2 id="developer-experience" tabindex="-1">Developer Experience <a class="header-anchor" href="#developer-experience" aria-label="Permalink to &quot;Developer Experience&quot;">​</a></h2><p>Modularous aims to provide a great Developer Experience when working on full-stack development process with:</p><ul><li>Presenting various custom artisan commands that undergo file generation</li><li>Generating CRUD pages and forms based on the defined model using ability of <a href="https://vuetifyjs.com/en/" target="_blank" rel="noreferrer">Vuetify.js</a></li><li>Simplistic configuration or customization on the CRM panel UI through config files</li><li>Simplistic configuration of CRUD forms through config files</li></ul><h2 id="organized-project-structure" tabindex="-1">Organized Project Structure <a class="header-anchor" href="#organized-project-structure" aria-label="Permalink to &quot;Organized Project Structure&quot;">​</a></h2><p>Modular approach trying to resolve the complexity with a default Laravel project structure where every business logic coming together in controllers. In modular approach, each business logic is split into different parts that communicate with each other.</p><p>Every module is similar to a Laravel project, each one has its own model, views, controllers and route files.</p><h2 id="dynamic-configurable-panel-ui" tabindex="-1">Dynamic &amp; Configurable Panel UI <a class="header-anchor" href="#dynamic-configurable-panel-ui" aria-label="Permalink to &quot;Dynamic &amp; Configurable Panel UI&quot;">​</a></h2><p>Powered by <a href="https://vuejs.org/guide/introduction.html" target="_blank" rel="noreferrer">Vue.js</a> and <a href="https://vuetifyjs.com/" target="_blank" rel="noreferrer">Vuetify.js</a>, your application&#39;s administration panel is auto-constructed while you developing your Laravel application.</p><p>With the abilities of Vuetify.js, Modularous presents various of dynamic, configurable UI components to auto-construct a CRM for your project.</p><h2 id="used-packages" tabindex="-1">Used Packages <a class="header-anchor" href="#used-packages" aria-label="Permalink to &quot;Used Packages&quot;">​</a></h2><ul><li><a href="https://github.com/nWidart/laravel-modules" target="_blank" rel="noreferrer">NWidart/Laravel-Modules</a> : is a Laravel package created to manage your large Laravel app using modules. A Module is like a Laravel package, it has some views, controllers or models</li></ul><h2 id="for-questions-and-issues" tabindex="-1">For Questions and Issues <a class="header-anchor" href="#for-questions-and-issues" aria-label="Permalink to &quot;For Questions and Issues&quot;">​</a></h2><p>Open a GitHub issue at <a href="https://github.com/unusualify/modularous/issues" target="_blank" rel="noreferrer">unusualify/modularous</a> for bug reports, questions, or feature requests.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><p>Planned improvements are tracked in the repository&#39;s GitHub Issues and Milestones. Community contributions are welcome — See <a href="https://github.com/unusualify/modularous/blob/11.x/.github/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> in the repository for guidelines.</p><h2 id="main-contributors" tabindex="-1">Main Contributors <a class="header-anchor" href="#main-contributors" aria-label="Permalink to &quot;Main Contributors&quot;">​</a></h2>',18),p=JSON.parse('{"title":"What is Modularous?","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"What is Modularous?"},"headers":[],"relativePath":"get-started/what-is-modularous.md","filePath":"get-started/what-is-modularous.md","lastUpdated":1778366969000}'),l={name:"get-started/what-is-modularous.md"},g=Object.assign(l,{setup(u){const e=[{avatar:"https://avatars.githubusercontent.com/u/47870922",name:"Oguzhan Bukcuoglu",title:"Creator / Full Stack Developer",links:[{icon:"github",link:"https://github.com/OoBook"}]},{avatar:"https://avatars.githubusercontent.com/u/76479640",name:"Erdem Çelik",title:"Full Stack Developer",links:[{icon:"github",link:"https://github.com/celikerde"}]},{avatar:"https://avatars.githubusercontent.com/u/45737685",name:"Hazarcan Doga Bakan",title:"Full Stack Developer",links:[{icon:"github",link:"https://github.com/dancing-janissary"}]},{avatar:"https://avatars.githubusercontent.com/u/80110747",name:"Ilker Ciblak",title:"Full Stack Developer",links:[{icon:"github",link:"https://github.com/ilkerciblak"}]},{avatar:"https://avatars.githubusercontent.com/u/37237628",name:"Gunes Bizim",title:"Full Stack Developer",links:[{icon:"github",link:"https://github.com/gunesbizim"}]}];return(c,h)=>(s(),t("div",null,[n,r(o(a),{size:"small",members:e})]))}});export{p as __pageData,g as default};
